import java.io.*;
import java.util.*;

import org.apache.commons.csv.*;

public class Main {
    public static void main(String[] args) throws IOException {
        Scanner in = new Scanner(System.in);
        int total = 0;
        while (in.hasNextLine()) {
            String[] kolom = in.nextLine().split(",");
            total += Integer.parseInt(kolom[1]);
        }
        System.out.println("Total: " + total);
    }
}

cards.solution:
import java.io.*;
import java.util.*;

import org.apache.commons.csv.*;

public class Main {
    public static void main(String[] args) throws IOException {
        int total = 0;
        for (CSVRecord r : CSVFormat.DEFAULT.parse(new InputStreamReader(System.in))) {
            total += Integer.parseInt(r.get(1));
        }
        System.out.println("Total: " + total);
    }
}
